			    var cmbBizYr = app.lookup("cmb5");
			    var cmbSrvcExcn = app.lookup("cmb2");
			    var cmbAltmntGroup = app.lookup("cmb1");
			    
			    cmbAltmntGroup.selectItemByValue(cmb4.getSelectionFirst().row.getValue("ALTMNT_GROUP_SCLAS_SE_CD"), false);
